198	// handleLifecycleTurnStart handles turn start: captures pre-prompt state,
199	// ensures strategy setup, initializes session.
200	func handleLifecycleTurnStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
201		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
202		logging.Info(logCtx, "turn-start",
203			slog.String("event", event.Type.String()),
204			slog.String("session_id", event.SessionID),
205			slog.String("session_ref", event.SessionRef),
206			slog.String("model", event.Model),
207		)
208	
209		sessionID := event.SessionID
210		if sessionID == "" {
211			return fmt.Errorf("no session_id in %s event", event.Type)
212		}
213		if err := validation.ValidateSessionID(sessionID); err != nil {
214			return fmt.Errorf("invalid %s event: %w", event.Type, err)
215		}
216	
217		// Fill model from hint file if the agent didn't provide it on this hook
218		if event.Model == "" {
219			if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
220				event.Model = hint
221				logging.Debug(logCtx, "loaded model from hint file",
222					slog.String("model", hint))
223			}
224		}
225	
226		// Capture pre-prompt state (including transcript position via TranscriptAnalyzer)
227		_, captureSpan := perf.Start(ctx, "capture_pre_prompt_state")
228		if err := CapturePrePromptState(ctx, ag, sessionID, event.SessionRef); err != nil {
229			captureSpan.RecordError(err)
230			captureSpan.End()
231			return err
232		}
233		captureSpan.End()
234	
235		// Append prompt to prompt.txt on filesystem so it's available for
236		// mid-turn commits (before SaveStep writes it to the shadow branch).
237		// Prompts are separated by "\n\n---\n\n" to support multiple turns.
238		if event.Prompt != "" {
239			sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
240			if sessionDirAbs, absErr := paths.AbsPath(ctx, sessionDir); absErr == nil {
241				if mkErr := os.MkdirAll(sessionDirAbs, 0o750); mkErr == nil {
242					promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
243					existing, readErr := os.ReadFile(promptPath) //nolint:gosec // session metadata path
244					var content string
245					if readErr == nil && len(existing) > 0 {
246						content = string(existing) + "\n\n---\n\n" + event.Prompt
247					} else {
248						content = event.Prompt
249					}
250					if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil { //nolint:gosec // path from internal metadata, not user input
251						logging.Warn(logCtx, "failed to write prompt.txt",
252							slog.String("error", writeErr.Error()))
253					}
254				}
255			}
256		}
257	
258		// Ensure strategy setup and initialize session
259		_, initSpan := perf.Start(ctx, "init_session")
260		if err := strategy.EnsureSetup(ctx); err != nil {
261			logging.Warn(logCtx, "failed to ensure strategy setup",
262				slog.String("error", err.Error()))
263		}
264	
265		strat := GetStrategy(ctx)
266		if err := strat.InitializeSession(ctx, sessionID, ag.Type(), event.SessionRef, event.Prompt, event.Model); err != nil {
267			logging.Warn(logCtx, "failed to initialize session state",
268				slog.String("error", err.Error()))
269		}
270		initSpan.End()
271	
272		return nil
273	}
274	
275	// handleLifecycleTurnEnd handles turn end: validates transcript, extracts metadata,
276	// detects file changes, saves step + checkpoint, transitions phase.
277	//
278	//nolint:maintidx // high complexity due to sequential orchestration of 8 steps (validation, extraction, file detection, filtering, token calc, step save, phase transition, cleanup) - splitting would obscure the flow
279	func handleLifecycleTurnEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
280		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
281		logging.Info(logCtx, "turn-end",
282			slog.String("event", event.Type.String()),
283			slog.String("session_id", event.SessionID),
284			slog.String("session_ref", event.SessionRef),
285			slog.String("model", event.Model),
286		)
287	
288		sessionID := event.SessionID
289		if sessionID == "" {
290			sessionID = unknownSessionID
291		}
292	
293		// Fill model from hint file if the agent didn't provide it on this hook
294		if event.Model == "" && sessionID != unknownSessionID {
295			if hint := strategy.LoadModelHint(ctx, sessionID); hint != "" {
296				event.Model = hint
297				logging.Debug(logCtx, "loaded model from hint file",
298					slog.String("model", hint))
299			}
300		}
301	
302		transcriptRef := event.SessionRef
303		if transcriptRef == "" {
304			return errors.New("transcript file not specified")
305		}
306	
307		// If agent implements TranscriptPreparer, materialize the transcript file.
308		// This must run BEFORE fileExists: agents like OpenCode lazily fetch transcripts
309		// via `opencode export`, so the file doesn't exist until PrepareTranscript creates it.
310		// Claude Code's PrepareTranscript just flushes (always succeeds). Agents without
311		// TranscriptPreparer (Gemini, Droid) are unaffected.
312		_, prepareSpan := perf.Start(ctx, "prepare_and_validate_transcript")
313		if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
314			if err := preparer.PrepareTranscript(ctx, transcriptRef); err != nil {
315				logging.Warn(logCtx, "failed to prepare transcript",
316					slog.String("error", err.Error()))
317			}
318		}
319	
320		if !fileExists(transcriptRef) {
321			prepareSpan.RecordError(fmt.Errorf("transcript file not found: %s", transcriptRef))
322			prepareSpan.End()
323			return fmt.Errorf("transcript file not found: %s", transcriptRef)
324		}
325	
326		// Early check: bail out quickly if the repo has no commits yet.
327		// Return nil (not an error) so the hook exits 0 — agents treat non-zero
328		// exit codes as hook failures. The user was already warned at session start.
329		if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
330			prepareSpan.End()
331			logging.Info(logCtx, "skipping checkpoint - will activate after first commit")
332			return nil
333		}
334		prepareSpan.End()
335	
336		// Create session metadata directory
337		_, copySpan := perf.Start(ctx, "copy_transcript")
338		sessionDir := paths.SessionMetadataDirFromSessionID(sessionID)
339		sessionDirAbs, err := paths.AbsPath(ctx, sessionDir)
340		if err != nil {
341			sessionDirAbs = sessionDir
342		}
343		if err := os.MkdirAll(sessionDirAbs, 0o750); err != nil {
344			copySpan.RecordError(err)
345			copySpan.End()
346			return fmt.Errorf("failed to create session directory: %w", err)
347		}
348	
349		// Copy transcript to session directory
350		transcriptData, err := ag.ReadTranscript(transcriptRef)
351		if err != nil {
352			copySpan.RecordError(err)
353			copySpan.End()
354			return fmt.Errorf("failed to read transcript: %w", err)
355		}
356		logFile := filepath.Join(sessionDirAbs, paths.TranscriptFileName)
357		if err := os.WriteFile(logFile, transcriptData, 0o600); err != nil {
358			copySpan.RecordError(err)
359			copySpan.End()
360			return fmt.Errorf("failed to write transcript: %w", err)
361		}
362		logging.Debug(logCtx, "copied transcript",
363			slog.String("path", sessionDir+"/"+paths.TranscriptFileName))
364		copySpan.End()
365	
366		// Load pre-prompt state (captured on TurnStart)
367		_, extractSpan := perf.Start(ctx, "extract_metadata")
368		preState, err := LoadPrePromptState(ctx, sessionID)
369		if err != nil {
370			logging.Warn(logCtx, "failed to load pre-prompt state",
371				slog.String("error", err.Error()))
372		}
373	
374		// Determine transcript offset
375		transcriptOffset := resolveTranscriptOffset(ctx, preState, sessionID)
376	
377		// Backfill prompt.txt from transcript when prompt data is missing.
378		// This handles agents whose exec mode doesn't fire UserPromptSubmit (e.g., Factory AI
379		// Droid). The transcript is the source of truth — if ExtractPrompts returns nothing,
380		// there genuinely were no prompts. We track whether backfill occurred so we can
381		// update session state after SaveStep (which may reinitialize state).
382		var backfilledPrompt string
383		promptPath := filepath.Join(sessionDirAbs, paths.PromptFileName)
384		existingPrompt, readPromptErr := os.ReadFile(promptPath) //nolint:gosec // file content is safe session metadata
385		if readPromptErr != nil && !os.IsNotExist(readPromptErr) {
386			logging.Warn(logCtx, "failed to read prompt.txt, skipping backfill",
387				slog.String("error", readPromptErr.Error()))
388		} else if len(existingPrompt) == 0 {
389			if extractor, ok := agent.AsPromptExtractor(ag); ok {
390				prompts, extractErr := extractor.ExtractPrompts(transcriptRef, transcriptOffset)
391				if extractErr != nil {
392					logging.Warn(logCtx, "failed to extract prompts from transcript",
393						slog.String("error", extractErr.Error()))
394				} else if len(prompts) > 0 {
395					content := strings.Join(prompts, "\n\n---\n\n")
396					if writeErr := os.WriteFile(promptPath, []byte(content), 0o600); writeErr != nil {
397						logging.Warn(logCtx, "failed to backfill prompt.txt from transcript",
398							slog.String("error", writeErr.Error()))
399					} else {
400						logging.Debug(logCtx, "backfilled prompt.txt from transcript",
401							slog.Int("prompt_count", len(prompts)))
402						backfilledPrompt = prompts[len(prompts)-1]
403					}
404				}
405			}
406		}
407	
408		// Compute subagents directory for agents that support subagent extraction.
409		// Subagent transcripts live in <transcriptDir>/<modelSessionID>/subagents/
410		subagentsDir := filepath.Join(filepath.Dir(transcriptRef), event.SessionID, "subagents")
411	
412		// Extract metadata via agent interface (modified files)
413		var modifiedFiles []string
414	
415		if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok {
416			// Extract modified files - prefer SubagentAwareExtractor if available to include subagent files
417			if subagentExtractor, subOk := agent.AsSubagentAwareExtractor(ag); subOk {
418				if files, fileErr := subagentExtractor.ExtractAllModifiedFiles(transcriptData, transcriptOffset, subagentsDir); fileErr != nil {
419					logging.Warn(logCtx, "failed to extract modified files (with subagents)",
420						slog.String("error", fileErr.Error()))
421				} else {
422					modifiedFiles = files
423				}
424			} else {
425				// Fall back to basic extraction (main transcript only)
426				if files, _, fileErr := analyzer.ExtractModifiedFilesFromOffset(transcriptRef, transcriptOffset); fileErr != nil {
427					logging.Warn(logCtx, "failed to extract modified files",
428						slog.String("error", fileErr.Error()))
429				} else {
430					modifiedFiles = files
431				}
432			}
433		}
434		extractSpan.End()
435	
436		// Generate commit message from last prompt (read from session state, set at TurnStart).
437		// In exec mode, session state LastPrompt may be empty because UserPromptSubmit never fires.
438		// Fall back to backfilledPrompt extracted from the transcript.
439		// Single load serves both prompt retrieval and backfill.
440		_, commitMsgSpan := perf.Start(ctx, "generate_commit_message")
441		lastPrompt := ""
442		if sessionState, stateErr := strategy.LoadSessionState(ctx, sessionID); stateErr == nil && sessionState != nil {
443			lastPrompt = sessionState.LastPrompt
444			// Backfill LastPrompt so `entire status` shows the prompt even when
445			// no files were modified (before the early return below).
446			if lastPrompt == "" && backfilledPrompt != "" {
447				lastPrompt = backfilledPrompt
448				sessionState.LastPrompt = backfilledPrompt
449				if saveErr := strategy.SaveSessionState(ctx, sessionState); saveErr != nil {
450					logging.Warn(logCtx, "failed to backfill LastPrompt in session state",
451						slog.String("error", saveErr.Error()))
452				}
453			}
454		} else if backfilledPrompt != "" {
455			lastPrompt = backfilledPrompt
456		}
457		commitMessage := generateCommitMessage(lastPrompt, ag.Type())
458		logging.Debug(logCtx, "using commit message",
459			slog.Int("message_length", len(commitMessage)))
460		commitMsgSpan.End()
461	
462		// Get worktree root for path normalization
463		_, detectSpan := perf.Start(ctx, "detect_file_changes")
464		repoRoot, err := paths.WorktreeRoot(ctx)
465		if err != nil {
466			detectSpan.RecordError(err)
467			detectSpan.End()
468			return fmt.Errorf("failed to get worktree root: %w", err)
469		}
470	
471		var preUntrackedFiles []string
472		if preState != nil {
473			logging.Debug(logCtx, "pre-prompt state",
474				slog.Int("pre_existing_untracked_files", len(preState.UntrackedFiles)))
475			preUntrackedFiles = preState.PreUntrackedFiles()
476		}
477	
478		// Detect file changes via git status
479		changes, err := DetectFileChanges(ctx, preUntrackedFiles)
480		if err != nil {
481			logging.Warn(logCtx, "failed to compute file changes",
482				slog.String("error", err.Error()))
483		}
484		detectSpan.End()
485	
486		// Filter and normalize all paths
487		_, normalizeSpan := perf.Start(ctx, "filter_and_normalize_paths")
488		relModifiedFiles := FilterAndNormalizePaths(modifiedFiles, repoRoot)
489		var relNewFiles, relDeletedFiles []string
490		if changes != nil {
491			relNewFiles = FilterAndNormalizePaths(changes.New, repoRoot)
492			relDeletedFiles = FilterAndNormalizePaths(changes.Deleted, repoRoot)
493	
494			// Merge git-status modified files as a fallback for transcript parsing.
495			// Transcript parsing is the primary source for modified files, but it can miss
496			// files if the agent uses an unrecognized tool or the transcript format changes.
497			// Git status catches any tracked file with working-tree changes.
498			relModifiedFiles = mergeUnique(relModifiedFiles, FilterAndNormalizePaths(changes.Modified, repoRoot))
499		}
500	
501		// Filter transcript-extracted files to exclude files already committed to HEAD.
502		// When an agent commits files mid-turn, those files are condensed by PostCommit
503		// and should not be re-added to FilesTouched by SaveStep. A file is "committed"
504		// if it exists in HEAD with the same content as the working tree.
505		relModifiedFiles = filterToUncommittedFiles(ctx, relModifiedFiles, repoRoot)
506		normalizeSpan.End()
507	
508		// Check if there are any changes
509		totalChanges := len(relModifiedFiles) + len(relNewFiles) + len(relDeletedFiles)
510		if totalChanges == 0 {
511			logging.Info(logCtx, "no files modified during session, skipping checkpoint")
512			transitionSessionTurnEnd(ctx, sessionID, event)
513			if cleanupErr := CleanupPrePromptState(ctx, sessionID); cleanupErr != nil {
514				logging.Warn(logCtx, "failed to cleanup pre-prompt state",
515					slog.String("error", cleanupErr.Error()))
516			}
517			return nil
518		}
519	
520		// Log file changes
521		logFileChanges(ctx, relModifiedFiles, relNewFiles, relDeletedFiles)
522	
523		// Get git author
524		author, err := GetGitAuthor(ctx)
525		if err != nil {
526			return fmt.Errorf("failed to get git author: %w", err)
527		}
528	
529		// Get strategy and agent type
530		strat := GetStrategy(ctx)
531		agentType := ag.Type()
532	
533		// Get transcript position/identifier from pre-prompt state
534		var transcriptIdentifierAtStart string
535		var transcriptLinesAtStart int
536		if preState != nil {
537			transcriptIdentifierAtStart = preState.LastTranscriptIdentifier
538			transcriptLinesAtStart = preState.TranscriptOffset
539		}
540	
541		// Calculate token usage - prefer SubagentAwareExtractor to include subagent tokens
542		tokenUsage := agent.CalculateTokenUsage(ctx, ag, transcriptData, transcriptLinesAtStart, subagentsDir)
543	
544		// Build fully-populated step context and delegate to strategy
545		stepCtx := strategy.StepContext{
546			SessionID:                sessionID,
547			ModifiedFiles:            relModifiedFiles,
548			NewFiles:                 relNewFiles,
549			DeletedFiles:             relDeletedFiles,
550			MetadataDir:              sessionDir,
551			MetadataDirAbs:           sessionDirAbs,
552			CommitMessage:            commitMessage,
553			TranscriptPath:           transcriptRef,
554			AuthorName:               author.Name,
555			AuthorEmail:              author.Email,
556			AgentType:                agentType,
557			StepTranscriptIdentifier: transcriptIdentifierAtStart,
558			StepTranscriptStart:      transcriptLinesAtStart,
559			TokenUsage:               tokenUsage,
560		}
561	
562		if err := strat.SaveStep(ctx, stepCtx); err != nil {
563			return fmt.Errorf("failed to save step: %w", err)
564		}
565	
566		// Update session state with backfilled prompt after SaveStep.
567		// Done after SaveStep because SaveStep may reinitialize session state,
568		// which would overwrite an earlier LastPrompt update.
569		if backfilledPrompt != "" {
570			if state, stateErr := strategy.LoadSessionState(ctx, sessionID); stateErr == nil && state != nil && state.LastPrompt == "" {
571				state.LastPrompt = backfilledPrompt
572				if saveErr := strategy.SaveSessionState(ctx, state); saveErr != nil {
573					logging.Warn(logCtx, "failed to backfill LastPrompt in session state",
574						slog.String("error", saveErr.Error()))
575				}
576			}
577		}
578	
579		// Transition session phase and cleanup
580		transitionSessionTurnEnd(ctx, sessionID, event)
581		if cleanupErr := CleanupPrePromptState(ctx, sessionID); cleanupErr != nil {
582			logging.Warn(logCtx, "failed to cleanup pre-prompt state",
583				slog.String("error", cleanupErr.Error()))
584		}
585	
586		return nil
587	}
