589	// handleLifecycleCompaction handles context compaction: saves current progress
590	// but stays in ACTIVE phase (unlike TurnEnd which transitions to IDLE).
591	// Also resets the transcript offset since the transcript may be truncated.
592	func handleLifecycleCompaction(ctx context.Context, ag agent.Agent, event *agent.Event) error {
593		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
594		logging.Info(logCtx, "compaction",
595			slog.String("event", event.Type.String()),
596			slog.String("session_id", event.SessionID),
597		)
598	
599		// Fire EventCompaction to trigger ActionCondenseIfFilesTouched (stays in ACTIVE)
600		sessionID := event.SessionID
601		sessionState, loadErr := strategy.LoadSessionState(ctx, sessionID)
602		if loadErr != nil {
603			logging.Warn(logCtx, "failed to load session state for compaction",
604				slog.String("error", loadErr.Error()))
605		}
606		if sessionState != nil {
607			persistEventMetadataToState(event, sessionState)
608	
609			if transErr := strategy.TransitionAndLog(ctx, sessionState, session.EventCompaction, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
610				logging.Warn(logCtx, "compaction transition failed",
611					slog.String("error", transErr.Error()))
612			}
613	
614			if saveErr := strategy.SaveSessionState(ctx, sessionState); saveErr != nil {
615				logging.Warn(logCtx, "failed to save session state after compaction",
616					slog.String("error", saveErr.Error()))
617			}
618		}
619	
620		logging.Info(logCtx, "context compaction detected")
621		return nil
622	}
