624	// handleLifecycleSessionEnd handles session end: marks the session as ended.
625	func handleLifecycleSessionEnd(ctx context.Context, ag agent.Agent, event *agent.Event) error {
626		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
627		logging.Info(logCtx, "session-end",
628			slog.String("event", event.Type.String()),
629			slog.String("session_id", event.SessionID),
630		)
631	
632		if event.SessionID == "" {
633			return nil // No session to update
634		}
635	
636		// Note: We intentionally don't clean up cached transcripts here.
637		// Post-session commits (carry-forward in ENDED phase) may still need
638		// the transcript to extract file changes. Cleanup is handled by
639		// `entire clean` or when the session state is fully removed.
640	
641		if err := markSessionEnded(ctx, event, event.SessionID); err != nil {
642			logging.Warn(logCtx, "failed to mark session ended",
643				slog.String("error", err.Error()))
644			// Don't attempt eager condense if we couldn't even mark the session ended —
645			// the session state may be in an inconsistent state.
646			return nil
647		}
648	
649		// Eagerly condense session data so PostCommit doesn't have to process it.
650		// This prevents zombie ENDED sessions from accumulating and causing O(N)
651		// overhead on every future commit (GitHub issue #591).
652		// Fail-open: if this fails, PostCommit will still process it on the next commit.
653		strat := GetStrategy(ctx)
654		if err := strat.CondenseAndMarkFullyCondensed(ctx, event.SessionID); err != nil {
655			logging.Warn(logCtx, "eager condense on session stop failed",
656				slog.String("session_id", event.SessionID),
657				slog.String("error", err.Error()))
658		}
659	
660		return nil
661	}
