842	// Returns parsed transcript lines for use with FindCheckpointUUID.
843	func parseTranscriptForCheckpointUUID(transcriptPath string) ([]transcriptLine, error) {
844		lines, err := transcript.ParseFromFileAtLine(transcriptPath, 0)
845		if err != nil {
846			return nil, fmt.Errorf("parsing transcript for checkpoint UUID: %w", err)
847		}
848		return lines, nil
