851	// transitionSessionTurnEnd transitions the session phase to IDLE and dispatches turn-end actions.
852	func transitionSessionTurnEnd(ctx context.Context, sessionID string, event *agent.Event) {
853		logCtx := logging.WithComponent(ctx, "lifecycle")
854		turnState, loadErr := strategy.LoadSessionState(ctx, sessionID)
855		if loadErr != nil {
856			logging.Warn(logCtx, "failed to load session state for turn end",
857				slog.String("error", loadErr.Error()))
858			return
859		}
860		if turnState == nil {
861			return
862		}
863	
864		persistEventMetadataToState(event, turnState)
865	
866		if err := strategy.TransitionAndLog(ctx, turnState, session.EventTurnEnd, session.TransitionContext{}, session.NoOpActionHandler{}); err != nil {
867			logging.Warn(logCtx, "turn-end transition failed",
868				slog.String("error", err.Error()))
869		}
870	
871		// Always dispatch to strategy for turn-end handling. The strategy reads
872		// work items from state (e.g. TurnCheckpointIDs), not the action list.
873		strat := GetStrategy(ctx)
874		if err := strat.HandleTurnEnd(ctx, turnState); err != nil {
875			logging.Warn(logCtx, "turn-end action dispatch failed",
876				slog.String("error", err.Error()))
877		}
878	
879		if updateErr := strategy.SaveSessionState(ctx, turnState); updateErr != nil {
880			logging.Warn(logCtx, "failed to update session phase on turn end",
881				slog.String("error", updateErr.Error()))
882		}
883	}
