885	// markSessionEnded transitions the session to ENDED phase via the state machine.
886	// If event is non-nil, hook-provided metrics are persisted to state before saving.
887	func markSessionEnded(ctx context.Context, event *agent.Event, sessionID string) error {
888		state, err := strategy.LoadSessionState(ctx, sessionID)
889		if err != nil {
890			return fmt.Errorf("failed to load session state: %w", err)
891		}
892		if state == nil {
893			return nil // No state file, nothing to update
894		}
895	
896		if event != nil {
897			persistEventMetadataToState(event, state)
898		}
899	
900		if transErr := strategy.TransitionAndLog(ctx, state, session.EventSessionStop, session.TransitionContext{}, session.NoOpActionHandler{}); transErr != nil {
901			logging.Warn(logging.WithComponent(ctx, "lifecycle"), "session stop transition failed",
902				slog.String("error", transErr.Error()))
903		}
904	
905		now := time.Now()
906		state.EndedAt = &now
907	
908		if err := strategy.SaveSessionState(ctx, state); err != nil {
909			return fmt.Errorf("failed to save session state: %w", err)
910		}
911		return nil
912	}
