914	// logFileChanges logs the files modified, created, and deleted during a session.
915	func logFileChanges(ctx context.Context, modified, newFiles, deleted []string) {
916		logCtx := logging.WithComponent(ctx, "lifecycle")
917		logging.Debug(logCtx, "files changed during session",
918			slog.Int("modified", len(modified)),
919			slog.Int("new", len(newFiles)),
920			slog.Int("deleted", len(deleted)))
921	}
922	
923	func persistEventMetadataToState(event *agent.Event, state *strategy.SessionState) {
924		// Update ModelName if provided (model is known by turn-end even on first turn)
925		if event.Model != "" {
926			state.ModelName = event.Model
927		}
928	
929		// Persist hook-provided session metrics (e.g., from Cursor hooks)
930		if event.DurationMs > 0 {
931			state.SessionDurationMs = event.DurationMs
932		}
933		// Use hook-reported turn count if available (take max); otherwise
934		// increment on each TurnEnd event to count turns ourselves.
935		if event.TurnCount > 0 {
936			if event.TurnCount > state.SessionTurnCount {
937				state.SessionTurnCount = event.TurnCount
938			}
939		} else if event.Type == agent.TurnEnd {
940			state.SessionTurnCount++
941		}
942		if event.ContextTokens > 0 {
943			state.ContextTokens = event.ContextTokens
944		}
945		if event.ContextWindowSize > 0 {
946			state.ContextWindowSize = event.ContextWindowSize
947		}
948	}
